#!/usr/bin/env python3
"""Reviewed Russian story overlay for canonical USA dialogue; raw ROMs unchanged.

Each list item corresponds to one original English sentence, including its
original paragraph advance. Repeated exact source passages share a translation.
"""
import hashlib
import json
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]


def segments(text):
    return [part.strip() for part in re.findall(r'[^.!?]+[.!?]?', text) if part.strip()]


def normalize(text):
    return re.sub(r'\s+', ' ', text).strip()


def lines(text):
    return [s.strip() for s in text.split('|')]


