def generate(root=ROOT):
    source_path = root / 'web/language-assets/en.json'
    source_bytes = source_path.read_bytes()
    source = json.loads(source_bytes)
    english = {key: value for key, value in source['strings'].items()
               if key.startswith('campaign.') or key.startswith('house.') and key.endswith('.intro')}
    unknown = set(REVIEWED) - english.keys()
    if unknown:
        raise ValueError('Unknown source keys: ' + repr(unknown))
    same_passage = {}
    for key, translated in REVIEWED.items():
        original = english[key]
        if len(segments(original)) != len(translated):
            raise ValueError(f'Sentence alignment mismatch {key}: {len(segments(original))} != {len(translated)}')
        same_passage[original] = translated
    strings, sentences, records, numeric_count = {}, {}, [], 0
    for key, original in english.items():
        translated = REVIEWED.get(key, same_passage.get(original))
        if translated is None:
            raise ValueError('Unreviewed canonical passage: ' + key)
        originals = segments(original)
        pairs = []
        for index, (en, ru) in enumerate(zip(originals, translated)):
            en = normalize(en)
            if re.findall(r'\d+', en) != re.findall(r'\d+', ru):
                raise ValueError('Changed gameplay number: ' + key)
            numeric_count += len(re.findall(r'\d+', en))
            if en in sentences and sentences[en] != ru:
                raise ValueError('Inconsistent duplicate sentence: ' + en)
            sentences[en] = ru
            pairs.append({'index': index, 'english': en, 'russian': ru})
        strings[key] = ' '.join(translated)
        records.append({'key': key, 'sentences': pairs})
    by_source_text = {original: strings[key] for key, original in english.items()}
    native_texts = {pointer: by_source_text[text] for pointer, text in source['nativeTexts'].items() if text in by_source_text}
    return {'version': 1, 'code': 'ru', 'sourceCode': 'en', 'strings': strings,
            'sentences': sentences, 'nativeTexts': native_texts, 'bySourceText': by_source_text,
            'segmentsByKey': {entry['key']: entry['sentences'] for entry in records},
            'review': {'source': 'Canonical Sega Genesis USA English story and hints',
                'sourceSha256': hashlib.sha256(source_bytes).hexdigest(),
                'method': 'Locally authored faithful Russian translation, reviewed against every canonical English sentence; exact repeated source passages reused.',
                'rawFanTranslationSha256': hashlib.sha256((root / 'web/language-assets/ru.json').read_bytes()).hexdigest(),
                'rawFanTranslationModified': False, 'gameplayModified': False,
                'normalization': 'English sentence split /[^.!?]+[.!?]?/; collapse whitespace and trim, preserving case, punctuation and native backticks.',
                'canonicalPassages': len(strings), 'canonicalSentenceOccurrences': sum(len(segments(t)) for t in english.values()),
                'uniqueSentenceTranslations': len(sentences), 'numericOccurrencesChecked': numeric_count,
                'coverage': 'All house introductions and all 3 houses x 9 missions x briefing/victory/defeat/hints',
                'names': {'Harkonnen': 'Харконнены', 'Atreides': 'Атрейдесы', 'Ordos': 'Ордосы',
                          'Radnor': 'Раднор', 'Cyril': 'Кирилл', 'Ammon': 'Аммон', 'Emperor Frederick': 'император Фредерик'},
                'terminology': {'spice': 'спайс', 'harvester': 'харвестер', 'Windtrap': 'ветроловушка',
                    'refinery': 'спайс-завод', 'Outpost': 'форпост', 'Barracks': 'казармы',
                    'Vehicle Factory': 'завод техники', 'Carryall': 'перевозчик', 'Rocket Turret': 'ракетная башня',
                    'Ornithopter': 'орнитоптер', 'Devastator': 'Девастатор', 'Deviator': 'Девиатор'}}}


def main():
    value = generate()
    data = (json.dumps(value, ensure_ascii=False, indent=2) + '\n').encode()
    for path in (ROOT / 'web/locale-story-ru.json', ROOT / 'data/locale-story-ru/locale-story-ru.json'):
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
    print(json.dumps(value['review'], ensure_ascii=False))


if __name__ == '__main__':
    main()
